<?php

declare(strict_types=1);

namespace App\Tests\Support\Security;

use Jose\Component\Core\AlgorithmManager;
use Jose\Component\Core\JWK;
use Jose\Component\Signature\Algorithm\HS256;
use Jose\Component\Signature\Algorithm\RS256;
use Jose\Component\Signature\JWSBuilder;
use Jose\Component\Signature\Serializer\CompactSerializer;

/**
 * Access tokens of both realms, signed with the key generated by tests/bootstrap.php.
 *
 * Claims given by a test replace the defaults; a null value removes the claim.
 */
final class TestTokenFactory
{
    public const string CUSTOMER_ID = '58276b79-2248-4817-8b28-5dbbb4f343ab';
    public const string STAFF_ID = 'f05dcc92-3f9f-41ba-a905-5325ece4a239';

    private const array AUDIENCES = ['shop' => 'shop-api', 'backoffice' => 'backoffice-api'];

    /**
     * @param array<string, mixed> $claims
     */
    public static function customer(array $claims = []): string
    {
        return self::forRealm('shop', [
            'sub' => self::CUSTOMER_ID,
            'email' => 'jan.kowalski@example.com',
            'name' => 'Jan Kowalski',
            'preferred_username' => 'jan.kowalski@example.com',
            ...$claims,
        ]);
    }

    /**
     * @param list<string>         $roles  realm roles in realm_access.roles
     * @param array<string, mixed> $claims
     */
    public static function staff(array $roles, array $claims = []): string
    {
        return self::forRealm('backoffice', [
            'sub' => self::STAFF_ID,
            'preferred_username' => 'admin',
            'realm_access' => ['roles' => $roles],
            ...$claims,
        ]);
    }

    /**
     * @param array<string, mixed> $claims
     */
    public static function forRealm(string $realm, array $claims): string
    {
        return self::sign(self::claimsFor($realm, $claims));
    }

    /**
     * Default claims of a valid access token of the realm, with the given ones applied.
     *
     * @param array<string, mixed> $claims
     *
     * @return array<string, mixed>
     */
    public static function claimsFor(string $realm, array $claims = []): array
    {
        $now = time();
        $merged = [
            'iss' => self::issuer($realm),
            'aud' => self::AUDIENCES[$realm] ?? 'unknown-api',
            'sub' => self::CUSTOMER_ID,
            'typ' => 'Bearer',
            'iat' => $now,
            'exp' => $now + 300,
            ...$claims,
        ];

        return array_filter($merged, static fn (mixed $value): bool => null !== $value);
    }

    /**
     * Signs the claims as a compact JWS with RS256 and the test key, or with the given key and algorithm.
     *
     * @param array<string, mixed> $claims
     */
    public static function sign(array $claims, ?JWK $key = null, string $algorithm = 'RS256'): string
    {
        $key ??= self::signingKey();
        $builder = new JWSBuilder(new AlgorithmManager([new RS256(), new HS256()]));
        $header = ['alg' => $algorithm, 'typ' => 'JWT'];
        if ($key->has('kid')) {
            $header['kid'] = $key->get('kid');
        }
        $jws = $builder->create()
            ->withPayload(json_encode($claims, \JSON_THROW_ON_ERROR))
            ->addSignature($key, $header)
            ->build();

        return (new CompactSerializer())->serialize($jws, 0);
    }

    public static function issuer(string $realm): string
    {
        return self::env('KEYCLOAK_PUBLIC_URL').'/realms/'.$realm;
    }

    public static function signingKey(): JWK
    {
        return JWK::createFromJson(self::env('OIDC_TEST_PRIVATE_JWK'));
    }

    private static function env(string $name): string
    {
        $value = $_SERVER[$name] ?? $_ENV[$name] ?? getenv($name);
        if (!\is_string($value) || '' === $value) {
            throw new \LogicException(\sprintf('The environment variable %s is not set.', $name));
        }

        return $value;
    }
}
